const item = $input.first().json;

if (!item.user_id || !item.active) {
  return [{ json: { valid: false } }];
}

return [{
  json: {
    valid: true,
    userId: item.user_id,
    role: item.role,
    active: item.active,
    user: {
      id: item.user_id,
      name: item.name,
      email: item.email,
      role: item.role,
      theme_header_color: item.theme_header_color,
      theme_main_color: item.theme_main_color,
      theme_accent_color: item.theme_accent_color,
    },
  },
}];

